import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date (supplied in the request, or the server date when omitted)
        // must fall on a business day: a weekend date rolls forward to the next Monday. Every value
        // derived from it (membership number year, daily-limit bucket) then uses this adjusted date.
        owner.setRegistrationDate(RegistrationDates.effective(owner.getRegistrationDate()));
        built.set(owner);
    }
}

